import { chainsFromSamRecords } from '../../LinearAlignmentsDisplay/samRecordFixture.ts'
import { computeDerivativePaths } from './computePaths.ts'

import type { SamRecordFixture } from '../../LinearAlignmentsDisplay/samRecordFixture.ts'

// A fold-back, which is the case the der(3) fixture cannot exercise: an allele
// that visits ONE chromosome twice, in opposite orientations. COLO829's chr9
// reads run out at 28,031,837 and resume inverted from 28,059,142, so the path
// is `chr9 -> chr9 (inverted)` and both of its segments carry the same refName.
// Everything that distinguishes a segment here is orientation and coordinate,
// which is exactly what a grouping keyed on refName alone would lose.
//
// A second call anchors 28 bp from the first (28,031,865 <-> 28,034,469), the
// signature of repeated breakage-fusion-bridge cycles re-breaking at one point,
// so this window holds more than one real allele. That is the other thing der(3)
// cannot show, where a single row is the whole answer.
//
// The window is narrower than the event on purpose: the arm a read returns from
// is named by its SA tag and does not have to be fetched. The tutorial figure
// uses the same window for the same reason, since 200x ONT over the whole event
// is more alignment than the track will load.
//
//   samtools view --input-fmt-option required_fields=0x87F -F 1540 \
//     https://ont-open-data.s3.amazonaws.com/colo829_2024.03/wf_somatic_variation/sup/COLO829_tumor.ht.cram \
//     chr9:28030000-28036000
